package com.javatpoint.servlets;
import java.io.*;import javax.servlet.*;import javax.servlet.annotation.*;import javax.servlet.http.*;import com.javatpoint.util.AuthUtil;
@WebServlet("/AddBookForm") public class AddBookForm extends HttpServlet{protected void doGet(HttpServletRequest q,HttpServletResponse r)throws ServletException,IOException{if(!AuthUtil.requireLibrarian(q,r))return;r.setContentType("text/html;charset=UTF-8");PrintWriter o=r.getWriter();o.print("<!doctype html><html><head><meta name='viewport' content='width=device-width,initial-scale=1'><title>Add book | eLibrary</title><link rel='stylesheet' href='bootstrap.min.css'><link rel='stylesheet' href='app.css'></head><body>");q.getRequestDispatcher("navlibrarian.html").include(q,r);q.getRequestDispatcher("addbookform.html").include(q,r);o.print("</body></html>");}}
